// Builds the "Grandma asleep in her armchair" proof of concept:
//   1. Grandma_SleepSit.anim: a looping humanoid clip (seated, slumped, head
//      lolled to one side) with two slow breaths, built from muscle curves.
//   2. Makes it the default state of Grandma.controller.
//   3. Seats Grandma_NPC in Grandma_Chair in House_Scene (fitted to the chair
//      mesh) and gives her a 3D snore (Assets/Sounds/Grandma/Grandma_Snore.wav,
//      generated by Tools/Audio/make_snore.py with the same breath timeline).
//
// Menu: Tools > Grandma > Build Sleeping Grandma. Batch mode:
//   Unity -batchmode -quit -projectPath . -executeMethod GrandmaSleepBuilder.Build
//   ... -executeMethod GrandmaSleepBuilder.RenderPreviews   (PNGs in Logs/GrandmaPreview)
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.Animations;
using UnityEditor.SceneManagement;
using UnityEngine;

public static class GrandmaSleepBuilder
{
    const string ClipPath = "Assets/Models/Grandma/Animation/Grandma_SleepSit.anim";
    const string ControllerPath = "Assets/Models/Grandma/Animation/Grandma.controller";
    const string SnorePath = "Assets/Sounds/Grandma/Grandma_Snore.wav";
    const string ScenePath = "Assets/Scenes/House_Scene.unity";
    const string GrandmaName = "Grandma_NPC";
    const string ChairName = "Grandma_Chair";

    // Must match Tools/Audio/make_snore.py.
    const float Length = 9f;
    static readonly (float inhaleStart, float inhaleEnd, float exhaleEnd, float depth)[] Breaths =
        { (0.00f, 1.90f, 4.20f, 1.00f), (4.30f, 6.50f, 8.90f, 1.25f) };

    // Seated, slumped, asleep (muscle values, -1..1).
    static readonly Dictionary<string, float> Pose = new Dictionary<string, float>
    {
        ["Spine Front-Back"] = 0.15f,      ["Chest Front-Back"] = 0.35f,     ["UpperChest Front-Back"] = 0.20f,
        ["Spine Left-Right"] = 0.06f,      ["Chest Left-Right"] = 0.05f,
        ["Neck Nod Down-Up"] = -0.60f,     ["Head Nod Down-Up"] = -0.40f,
        ["Neck Tilt Left-Right"] = 0.45f,  ["Head Tilt Left-Right"] = 0.40f,
        ["Neck Turn Left-Right"] = 0.08f,  ["Head Turn Left-Right"] = 0.12f,

        ["Left Upper Leg Front-Back"] = -0.875f, ["Right Upper Leg Front-Back"] = -0.865f,
        ["Left Lower Leg Stretch"] = -0.10f,    ["Right Lower Leg Stretch"] = -0.13f,

        ["Left Shoulder Down-Up"] = -0.25f,  ["Right Shoulder Down-Up"] = -0.25f,
        ["Left Arm Down-Up"] = -0.85f,       ["Right Arm Down-Up"] = -0.80f,
        ["Left Arm Front-Back"] = -0.15f,    ["Right Arm Front-Back"] = -0.05f,
        ["Left Forearm Stretch"] = 0.55f,    ["Right Forearm Stretch"] = 0.55f,
    };

    // Added at the top of a normal-depth inhale: chest lifts and opens,
    // shoulders rise, the lolled head comes up a touch.
    static readonly Dictionary<string, float> Inhale = new Dictionary<string, float>
    {
        ["Spine Front-Back"] = -0.035f, ["Chest Front-Back"] = -0.06f, ["UpperChest Front-Back"] = -0.05f,
        ["Left Shoulder Down-Up"] = 0.07f, ["Right Shoulder Down-Up"] = 0.07f,
        ["Neck Nod Down-Up"] = 0.03f, ["Head Nod Down-Up"] = 0.04f,
        ["Left Arm Down-Up"] = 0.015f, ["Right Arm Down-Up"] = 0.015f,
    };

    const float RootHeight = 0.55f;   // body centre height in the clip; the scene placement fits her to the seat

    [MenuItem("Tools/Grandma/Build Sleeping Grandma")]
    public static void Build()
    {
        var clip = BuildClip();
        SetupController(clip);
        SetupAudio();
        PlaceInScene(clip);
    }

    public static void BuildAndPreview() { Build(); RenderPreviews(); }

    // 0 when resting, 1 at the top of a normal breath (deep breath goes past 1).
    static float Breath(float t)
    {
        foreach (var (a, b, c, depth) in Breaths)
        {
            if (t >= a && t <= b) { float u = (t - a) / (b - a); return depth * u * u * (3 - 2 * u); }
            if (t > b && t <= c) { float u = (t - b) / (c - b); return depth * Mathf.Pow(1 - u, 1.7f); }
        }
        return 0f;
    }

    // Only the second, deeper breath: her head lolls a little further over.
    static float DeepBreath(float t)
    {
        var (a, b, c, _) = Breaths[1];
        if (t < a || t > c) return 0f;
        return Mathf.Sin(Mathf.PI * (t - a) / (c - a));
    }

    static float Value(string muscle, float t)
    {
        Pose.TryGetValue(muscle, out float v);
        if (Inhale.TryGetValue(muscle, out float d)) v += d * Breath(t);
        if (muscle == "Neck Tilt Left-Right") v += 0.04f * DeepBreath(t);
        if (muscle == "Head Tilt Left-Right") v += 0.02f * Mathf.Sin(2 * Mathf.PI * t / Length);
        if (muscle == "Head Turn Left-Right") v += 0.015f * Mathf.Sin(4 * Mathf.PI * t / Length + 1f);
        return v;
    }

    static AnimationClip BuildClip()
    {
        var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(ClipPath);
        if (clip == null)
        {
            clip = new AnimationClip { name = "Grandma_SleepSit" };
            AssetDatabase.CreateAsset(clip, ClipPath);
        }
        clip.ClearCurves();
        clip.frameRate = 30;

        const float step = 0.1f;
        int n = Mathf.RoundToInt(Length / step);
        foreach (var muscle in Pose.Keys.Union(Inhale.Keys))
        {
            var keys = new Keyframe[n + 1];
            for (int i = 0; i <= n; i++)
            {
                float t = i * step;
                float slope = (Value(muscle, Mathf.Min(t + 0.01f, Length)) - Value(muscle, Mathf.Max(t - 0.01f, 0f)))
                            / (Mathf.Min(t + 0.01f, Length) - Mathf.Max(t - 0.01f, 0f));
                keys[i] = new Keyframe(t, Value(muscle, t), slope, slope);
            }
            AnimationUtility.SetEditorCurve(clip, EditorCurveBinding.FloatCurve("", typeof(Animator), muscle), new AnimationCurve(keys));
        }
        void Const(string attr, float v) => AnimationUtility.SetEditorCurve(clip,
            EditorCurveBinding.FloatCurve("", typeof(Animator), attr), AnimationCurve.Constant(0, Length, v));
        Const("RootT.x", 0); Const("RootT.y", RootHeight); Const("RootT.z", 0);
        Const("RootQ.x", 0); Const("RootQ.y", 0); Const("RootQ.z", 0); Const("RootQ.w", 1);

        var s = AnimationUtility.GetAnimationClipSettings(clip);
        s.loopTime = true;
        s.loopBlendOrientation = s.loopBlendPositionY = s.loopBlendPositionXZ = true;
        s.keepOriginalOrientation = s.keepOriginalPositionY = s.keepOriginalPositionXZ = true;
        s.stopTime = Length;
        AnimationUtility.SetAnimationClipSettings(clip, s);
        EditorUtility.SetDirty(clip);
        AssetDatabase.SaveAssets();
        Debug.Log($"[GrandmaSleep] clip {ClipPath}: {Pose.Count} muscles, {Length}s");
        return clip;
    }

    static void SetupController(AnimationClip clip)
    {
        var ctrl = AssetDatabase.LoadAssetAtPath<AnimatorController>(ControllerPath);
        var sm = ctrl.layers[0].stateMachine;
        var state = sm.states.Select(c => c.state).FirstOrDefault(st => st.name == "SleepSit")
                    ?? sm.AddState("SleepSit", new Vector3(300, 120, 0));
        state.motion = clip;
        sm.defaultState = state;
        EditorUtility.SetDirty(ctrl);
        AssetDatabase.SaveAssets();
    }

    static void SetupAudio()
    {
        AssetDatabase.ImportAsset(SnorePath, ImportAssetOptions.ForceSynchronousImport);
        var imp = (AudioImporter)AssetImporter.GetAtPath(SnorePath);
        imp.forceToMono = true;
        imp.loadInBackground = false;
        var ss = imp.defaultSampleSettings;
        ss.loadType = AudioClipLoadType.DecompressOnLoad;
        ss.compressionFormat = AudioCompressionFormat.PCM;
        ss.preloadAudioData = true;
        imp.defaultSampleSettings = ss;
        imp.SaveAndReimport();
    }

    // ── Placement ──────────────────────────────────────────────────────────
    // The armchair was modelled at Grandma's own scale (3.1) and swallowed her:
    // the seat was deeper than her thighs are long, so her shins went through
    // the cushion. A touch smaller, and she sits with her knees past its edge.
    const float ChairScale = 2.75f;
    const float KneePastSeatEdge = 0.20f;   // world units: knee joints this far in front of the cushion's front edge
    const float HipsAboveSeat = 0.28f;      // world units: hip joints above the cushion top (she sinks in a little)

    // Seat space: origin on top of the cushion at its centre; x right, y up, z out the front.
    internal struct ChairFit
    {
        public Vector3 front, right, origin;
        public float floor, cushionFront, backFace;
        public Vector3 Rel(Vector3 world) { var d = world - origin; return new Vector3(Vector3.Dot(d, right), d.y, Vector3.Dot(d, front)); }
    }

    internal static ChairFit MeasureChair(GameObject chair)
    {
        float s = chair.transform.lossyScale.x;
        var verts = new List<Vector3>();
        foreach (var mf in chair.GetComponentsInChildren<MeshFilter>())
            verts.AddRange(mf.sharedMesh.vertices.Select(v => mf.transform.TransformPoint(v)));
        float floor = verts.Min(v => v.y);
        Vector3 all = Avg(verts);
        Vector3 high = Avg(verts.Where(v => v.y > floor + 0.75f * s));
        Vector3 front = all - high; front.y = 0; front.Normalize();
        Vector3 right = Vector3.Cross(Vector3.up, front);
        var seat = verts.Where(v => v.y < floor + 0.6f * s
                                 && Mathf.Abs(Vector3.Dot(v - all, right)) < 0.15f * s
                                 && Vector3.Dot(v - all, front) is float f && f > -0.10f * s && f < 0.20f * s).ToList();
        Vector3 origin = Avg(seat); origin.y = seat.Max(v => v.y);
        var fit = new ChairFit { front = front, right = right, origin = origin, floor = floor };
        var rel = verts.Select(fit.Rel).Where(v => Mathf.Abs(v.x) < 0.15f * s).ToList();
        fit.cushionFront = rel.Where(v => v.y > -0.10f * s && v.y < 0.02f * s).Max(v => v.z);
        fit.backFace = rel.Where(v => v.y > 0.15f * s && v.y < 0.30f * s).Select(v => v.z).DefaultIfEmpty(float.NaN).Max();
        return fit;
    }

    static Vector3 Avg(IEnumerable<Vector3> vs) { var l = vs.ToList(); return l.Aggregate(Vector3.zero, (a, b) => a + b) / l.Count; }

    // Pose her at time t (inside AnimationMode; StopAnimationMode() puts the
    // bones back). Matches what the Animator shows in Play mode.
    static void Sample(GameObject go, float t)
    {
        var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(ClipPath);
        if (!AnimationMode.InAnimationMode()) AnimationMode.StartAnimationMode();
        AnimationMode.BeginSampling();
        AnimationMode.SampleAnimationClip(go, clip, t);
        AnimationMode.EndSampling();
    }

    // Bone transforms, so measuring/previewing doesn't leave pose overrides in the scene.
    static List<(Transform tr, Vector3 p, Quaternion r, Vector3 s)> Snapshot(GameObject go) =>
        go.GetComponentsInChildren<Transform>(true).Where(t => t != go.transform)
          .Select(t => (t, t.localPosition, t.localRotation, t.localScale)).ToList();

    static void Restore(List<(Transform tr, Vector3 p, Quaternion r, Vector3 s)> snap)
    {
        foreach (var (tr, p, r, sc) in snap) { tr.localPosition = p; tr.localRotation = r; tr.localScale = sc; }
    }

    static void PlaceInScene(AnimationClip clip)
    {
        var scene = EditorSceneManager.OpenScene(ScenePath, OpenSceneMode.Single);
        var gm = GameObject.Find(GrandmaName);
        var chair = GameObject.Find(ChairName);
        var anim = gm.GetComponent<Animator>();

        chair.transform.localScale *= ChairScale / chair.transform.lossyScale.x;   // pivot is on the floor
        var fit = MeasureChair(chair);

        // Hips centred, just above the cushion; slid forward until both knees
        // hang past the front edge of the seat.
        gm.transform.rotation = Quaternion.LookRotation(fit.front, Vector3.up);
        var rest = Snapshot(gm);
        for (int i = 0; i < 4; i++)
        {
            Sample(gm, 0f);
            Vector3 hips = fit.Rel(anim.GetBoneTransform(HumanBodyBones.Hips).position);
            float knee = Mathf.Min(fit.Rel(anim.GetBoneTransform(HumanBodyBones.LeftLowerLeg).position).z,
                                   fit.Rel(anim.GetBoneTransform(HumanBodyBones.RightLowerLeg).position).z);
            AnimationMode.StopAnimationMode();
            Restore(rest);
            gm.transform.position += fit.right * -hips.x + Vector3.up * (HipsAboveSeat - hips.y)
                                   + fit.front * (fit.cushionFront + KneePastSeatEdge - knee);
        }
        Sample(gm, 0f);
        Debug.Log("[GrandmaSleep] " + Measure(gm, chair));
        AnimationMode.StopAnimationMode();
        Restore(rest);

        // Snore, from her head.
        var head = anim.GetBoneTransform(HumanBodyBones.Head);
        var srcGo = head.Find("SnoreSource")?.gameObject ?? new GameObject("SnoreSource");
        srcGo.transform.SetParent(head, false);
        srcGo.transform.localPosition = Vector3.zero;
        if (!srcGo.TryGetComponent(out AudioSource src)) src = srcGo.AddComponent<AudioSource>();
        src.clip = AssetDatabase.LoadAssetAtPath<AudioClip>(SnorePath);
        src.loop = true;
        src.playOnAwake = true;
        src.volume = 0.9f;
        src.spatialBlend = 1f;
        src.rolloffMode = AudioRolloffMode.Logarithmic;
        src.minDistance = 4f;      // world is ~3x real scale
        src.maxDistance = 35f;
        src.dopplerLevel = 0f;
        src.priority = 64;

        if (!gm.TryGetComponent(out GrandmaSleep_Script sleep)) sleep = gm.AddComponent<GrandmaSleep_Script>();
        sleep.snore = src;
        anim.applyRootMotion = false;

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        Debug.Log($"[GrandmaSleep] placed {GrandmaName} at {gm.transform.position:F3} rot {gm.transform.eulerAngles:F1}, chair scale {chair.transform.lossyScale.x:F2}");
    }

    // How she sits in the chair right now, in seat space (world units), from
    // her bones and her skinned surface. Used to tune the pose, in the editor
    // and in Play mode.
    internal static string Measure(GameObject gm, GameObject chair)
    {
        var a = gm.GetComponent<Animator>();
        var fit = MeasureChair(chair);
        float seatHeight = fit.origin.y - fit.floor;
        Vector3 R(HumanBodyBones b) => fit.Rel(a.GetBoneTransform(b).position);
        string P(HumanBodyBones b) { var r = R(b); return $"{b}(fwd {r.z:F2} up {r.y:F2} right {r.x:F2})"; }

        var body = new List<Vector3>();
        foreach (var smr in gm.GetComponentsInChildren<SkinnedMeshRenderer>())
        {
            var m = new Mesh();
            smr.BakeMesh(m, true);
            body.AddRange(m.vertices.Select(v => fit.Rel(smr.transform.TransformPoint(v))));
            Object.DestroyImmediate(m);
        }
        float hipsZ = R(HumanBodyBones.Hips).z, kneeZ = Mathf.Min(R(HumanBodyBones.LeftLowerLeg).z, R(HumanBodyBones.RightLowerLeg).z);
        var thighs = body.Where(v => v.z > hipsZ + 0.15f && v.z < kneeZ - 0.30f && Mathf.Abs(v.x) < 0.7f).ToList();
        var inSeat = body.Where(v => v.z < fit.cushionFront - 0.03f && v.y < -0.08f && v.y > 0.3f - seatHeight && Mathf.Abs(v.x) < 0.9f).ToList();
        var back = body.Where(v => v.y > 0.6f && v.y < 1.5f).ToList();
        return $"chair scale {chair.transform.lossyScale.x:F2}, seat {seatHeight:F2} above floor, cushion front edge fwd {fit.cushionFront:F2}, back cushion fwd {fit.backFace:F2}\n  "
            + string.Join("\n  ", new[] { HumanBodyBones.Hips, HumanBodyBones.Head, HumanBodyBones.LeftLowerLeg, HumanBodyBones.RightLowerLeg,
                HumanBodyBones.LeftFoot, HumanBodyBones.RightFoot, HumanBodyBones.LeftToes, HumanBodyBones.RightToes,
                HumanBodyBones.LeftHand, HumanBodyBones.RightHand }.Select(P))
            + $"\n  soles above floor {body.Min(v => v.y) + seatHeight:F2}"
            + $"\n  thigh underside above cushion {(thighs.Count > 0 ? thighs.Min(v => v.y) : float.NaN):F2}"
            + $"\n  surface points inside the seat block {inSeat.Count} (deepest {(inSeat.Count > 0 ? inSeat.Min(v => v.y) : 0f):F2})"
            + $"\n  gap between her back and the back cushion {back.Min(v => v.z) - fit.backFace:F2}";
    }

    // ── Previews ───────────────────────────────────────────────────────────
    public static void RenderPreviews()
    {
        EditorSceneManager.OpenScene(ScenePath, OpenSceneMode.Single);
        var gm = GameObject.Find(GrandmaName);
        var anim = gm.GetComponent<Animator>();
        var fit = MeasureChair(GameObject.Find(ChairName));
        Directory.CreateDirectory("Logs/GrandmaPreview");

        var camGo = new GameObject("PreviewCam");
        var cam = camGo.AddComponent<Camera>();
        cam.fieldOfView = 50; cam.nearClipPlane = 0.05f;
        cam.clearFlags = CameraClearFlags.SolidColor; cam.backgroundColor = Color.black;
        var fillGo = new GameObject("PreviewFill");
        var fill = fillGo.AddComponent<Light>();
        fill.type = LightType.Point; fill.range = 20; fill.intensity = 1.2f;
        var rt = new RenderTexture(960, 720, 24);
        cam.targetTexture = rt;

        Vector3 seat = fit.origin, right = fit.right;
        var views = new (string name, Vector3 pos, Vector3 look)[]
        {
            ("front", seat + fit.front * 7f + right * 2.5f + Vector3.up * 3.2f, seat + Vector3.up * 1.6f),
            ("side",  seat + right * 7.5f + fit.front * 1f + Vector3.up * 2.5f, seat + Vector3.up * 1.4f),
            ("head",  seat + fit.front * 2.6f + right * 0.8f + Vector3.up * 3.6f, seat + Vector3.up * 2.9f),
            ("legs",  seat + right * 6f + fit.front * 1.5f + Vector3.up * 0.3f, seat + fit.front * 1.0f - Vector3.up * 0.3f),
            ("player", seat + fit.front * 9f - right * 3f + Vector3.up * 5.2f, seat + Vector3.up * 1.8f),
        };
        foreach (var (t, tag) in new[] { (0f, "rest"), (1.9f, "inhale"), (5.8f, "deep") })
        {
            Sample(gm, t);
            foreach (var (name, pos, look) in views)
            {
                foreach (bool lit in new[] { true, false })
                {
                    if (!lit && name != "player") continue;
                    fill.enabled = lit;
                    camGo.transform.position = pos;
                    camGo.transform.LookAt(look);
                    fillGo.transform.position = pos + Vector3.up * 1f;
                    cam.Render();
                    RenderTexture.active = rt;
                    var tex = new Texture2D(rt.width, rt.height, TextureFormat.RGB24, false);
                    tex.ReadPixels(new Rect(0, 0, rt.width, rt.height), 0, 0);
                    tex.Apply();
                    File.WriteAllBytes($"Logs/GrandmaPreview/{name}_{tag}{(lit ? "" : "_scenelight")}.png", tex.EncodeToPNG());
                    RenderTexture.active = null;
                }
            }
        }
        AnimationMode.StopAnimationMode();
        Object.DestroyImmediate(camGo); Object.DestroyImmediate(fillGo);
        Debug.Log("[GrandmaSleep] previews written to Logs/GrandmaPreview");
    }
}
